// ZUI JS Placeholder - Replace with actual ZUI JS
(function($) {
    'use strict';
    
    // Messager
    $.zui = $.zui || {};
    $.zui.Messager = function(message, options) {
        this.message = message;
        this.options = $.extend({
            type: 'info',
            icon: 'info-sign',
            time: 3000,
            placement: 'top'
        }, options);
    };
    
    $.zui.Messager.prototype.show = function() {
        var $msg = $('<div class="alert alert-' + this.options.type + '" style="position:fixed;top:20px;right:20px;z-index:9999;min-width:200px;">' +
            '<i class="icon icon-' + this.options.icon + '"></i> ' + this.message +
            '</div>');
        $('body').append($msg);
        setTimeout(function() {
            $msg.fadeOut(function() {
                $msg.remove();
            });
        }, this.options.time);
    };
    
})(jQuery);
